import Carbon.HIToolbox
import Foundation
@testable import DockGroupsCore

/// Files written by version 0.8.0 (`8127967`), byte for byte: the groups file, the preferences file,
/// a standalone group's agent configuration and a backup. The groups hold every kind of item, Free
/// Layout cells, popup overrides, Start and Finish settings and launch options (a delay; the app
/// that opens a file or folder); the preferences differ from the defaults everywhere and protect an
/// app. Generated by building that version's DockGroupsCore and saving these values with it.
///
/// `groupsFileWithShortcuts` and `backupWithShortcuts` are what this version writes for the same
/// groups once they have keyboard shortcuts. Read by that build of 0.8.0 and saved again, they gave
/// `groupsFile` and `backup` back byte for byte (the backup's `appVersion` aside), with the groups
/// equal to `codingGroup` and `designGroup`: 0.8.0 ignores the `shortcut` key, and drops it when it
/// saves. Its agent configuration is `agentConfiguration` itself: agents never get the shortcut.
enum Version080Fixtures {
    static var codingGroup: DockGroup {
        var report = GroupItem(fileURL: URL(fileURLWithPath: "/Users/me/Documents/Q3 Report.pdf"), kind: .file)
        report.details = ItemDetails(alias: "Quarterly report", tags: ["finance", "q3"], notes: "Send totals\non Fridays")
        report.launch = ItemLaunchOptions(delay: 3, opener: ItemOpener(bundleIdentifier: "com.apple.Preview", name: "Preview"))
        var projects = GroupItem(fileURL: URL(fileURLWithPath: "/Users/me/Projects/cybokron", isDirectory: true), kind: .folder)
        projects.launch = ItemLaunchOptions(opener: ItemOpener(bundleIdentifier: "com.microsoft.VSCode", name: "Visual Studio Code"))
        var xcode = AppReference(bundleIdentifier: "com.apple.dt.Xcode", name: "Xcode", path: "/Applications/Xcode.app")
        xcode.details = ItemDetails(tags: ["dev"])
        var slack = AppReference(bundleIdentifier: "com.tinyspeck.slackmacgap", name: "Slack")
        slack.launch = ItemLaunchOptions(delay: 5)
        return DockGroup(
            id: UUID(uuidString: "0C0D1E00-0000-4000-8000-000000000080")!,
            name: "Coding",
            emoji: "💻",
            apps: [
                xcode,
                slack,
                projects,
                report,
                AppReference(websiteURL: URL(string: "https://github.com/cybokron")!, name: "Cybokron"),
            ],
            tile: TileAppearance(kind: .grid),
            isPinned: true,
            isStandalone: true,
            popup: PopupOverrides(columns: .fixed(4), maxRows: 2),
            freeLayoutSlots: [projects.normalizedBundleIdentifier: 2, "com.apple.dt.xcode": 0],
            switching: GroupSwitching(onStart: .quitPreviousGroup, onFinish: .hideApps, afterFinish: .nothing)
        )
    }
    static let designGroup = DockGroup(
        id: UUID(uuidString: "0DE51600-0000-4000-8000-000000000080")!,
        name: "Design",
        emoji: "🎨",
        apps: [AppReference(bundleIdentifier: "com.figma.Desktop", name: "Figma")]
    )
    static let preferences = PopupPreferences(
        theme: .light, usesFrostedGlass: false, columns: .fixed(5), maxRows: 3, showsTitles: false,
        anchor: .dockIcon, usesFreeLayout: true, shortcutsEnabled: true, shortcutModifiers: .controlCommand,
        showsMostUsed: false, mostUsedLimit: 5, mostUsedSessionSeconds: 900, automaticallyChecksForUpdates: false,
        showsStandaloneDockMenus: false, restoresWindowsOfRunningApps: false, language: .specific("tr"),
        protectedApps: ProtectedApps([AppReference(bundleIdentifier: "com.apple.Music", name: "Music")])
    )
    static let exportedAt = Date(timeIntervalSince1970: 1_793_100_000)

    /// ⌃⌥C starts Coding (finishes it when it's current); ⌃⌥D shows Design's popup.
    static let codingShortcut = GroupShortcut(keys: KeyCombination(keyCode: UInt16(kVK_ANSI_C), modifiers: [.control, .option]), action: .startOrFinish)!
    static let designShortcut = GroupShortcut(keys: KeyCombination(keyCode: UInt16(kVK_ANSI_D), modifiers: [.control, .option]))!

    /// The groups with their shortcuts.
    static var groupsWithShortcuts: [DockGroup] {
        var coding = codingGroup
        coding.shortcut = codingShortcut
        var design = designGroup
        design.shortcut = designShortcut
        return [coding, design]
    }

